class Solution:
    def isStrobogrammatic(self, num: str) -> bool:
        def match(a, b):
            if a in {'0', '1', '8'}:
                return a == b
            if a == '6':
                return b == '9'
            if a == '9':
                return b == '6'
            return False
        n = len(num)
        i, j = 0, n - 1
        while i <= j:
            if not match(num[i], num[j]):
                return False
            i += 1
            j -= 1
        return True

class Solution {
    public boolean isStrobogrammatic(String num) {
        int n = num.length();
        for (int i = 0, j = n - 1; i <= j; ++i, --j) {
            if (!match(num.charAt(i), num.charAt(j))) return false;
        }
        return true;
    }

    private boolean match(char a, char b) {
        switch (a) {
            case '0':
            case '1':
            case '8':
                return a == b;
            case '6':
                return b == '9';
            case '9':
                return b == '6';
            default:
                return false;
        }
    }
}

class Solution:
    def isStrobogrammatic(self, num):
        """
        :type num: str
        :rtype: bool
        """
        d = {"0": "0", "1": "1", "6": "9", "8": "8", "9": "6"}
        strobogrammatic = ""
        for i in num[::-1]:
            if i in d:
                strobogrammatic += d[i]
            else:
                return False
        return strobogrammatic == num

class Solution(object):
    def isStrobogrammatic(self, num):
        """
        :type num: str
        :rtype: bool
        """
        pairs = {"1":"1","0":"0", "8":"8", "6":"9","9":"6"}
        if len(num)%2==0:
            half = len(num)/2
        else:
            half = len(num)/2+1
        for i in range(half):
            if num[i] not in pairs:
                return False
            if pairs[num[i]]!=num[len(num)-1-i]:
                return False
        return True

package twopointer;

import java.util.Map;

/**
 * LeetCode 246 - Strobogrammatic Number
 * <p>
 * A strobogrammatic number looks the same when rotated 180 degrees.
 * Valid digit pairs (left -> right when rotated): 0->0, 1->1, 6->9, 8->8, 9->6
 * <p>
 * Approach: Two pointers from both ends, check each pair against the valid map.
 * Time: O(n), Space: O(1)
 */
public class StrobogrammaticNumber {

    public boolean isStrobogrammatic(String num) {
        Map<Character, Character> map = Map.of
                (
                        '0', '0',
                        '1', '1',
                        '6', '9',
                        '8', '8',
                        '9', '6'
                );
        int i = 0;
        int j = num.length() - 1;
        while (i <= j) {
            char left = num.charAt(i);
            char right = num.charAt(j);
            if (!map.containsKey(left) || map.get(left) != right) {
                return false;
            }
            i++;
            j--;
        }
        return true;
    }

    public static void main(String[] args) {
        StrobogrammaticNumber sol = new StrobogrammaticNumber();

        // Test 1: "69" → true
        System.out.println(sol.isStrobogrammatic("69"));   // true

        // Test 2: "88" → true
        System.out.println(sol.isStrobogrammatic("88"));   // true

        // Test 3: "962" → false
        System.out.println(sol.isStrobogrammatic("962"));  // false

        // Test 4: "1" → true (single digit, middle element)
        System.out.println(sol.isStrobogrammatic("1"));    // true

        // Test 5: "2" → false
        System.out.println(sol.isStrobogrammatic("2"));    // false

        // Test 6: "818" → true
        System.out.println(sol.isStrobogrammatic("818"));  // true

        // Test 7: "619" → true
        System.out.println(sol.isStrobogrammatic("619"));  // true
    }
}
